// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.28;

import {IVersion} from "../../interfaces/decent/deployables/IVersion.sol";
import {IPaymaster} from "@account-abstraction/contracts/interfaces/IPaymaster.sol";
import {IEntryPoint} from "@account-abstraction/contracts/interfaces/IEntryPoint.sol";
import {UserOperationLib, PackedUserOperation} from "@account-abstraction/contracts/core/UserOperationLib.sol";
import {IERC165} from "@openzeppelin/contracts/utils/introspection/IERC165.sol";

/**
 * Helper class for creating a paymaster.
 * provides helper methods for staking.
 * Validates that the postOp is called only by the entryPoint.
 */
abstract contract BasePaymasterV1 is IPaymaster, IVersion {
    IEntryPoint public entryPoint;
    address public owner;

    uint256 internal constant PAYMASTER_VALIDATION_GAS_OFFSET =
        UserOperationLib.PAYMASTER_VALIDATION_GAS_OFFSET;
    uint256 internal constant PAYMASTER_POSTOP_GAS_OFFSET =
        UserOperationLib.PAYMASTER_POSTOP_GAS_OFFSET;
    uint256 internal constant PAYMASTER_DATA_OFFSET =
        UserOperationLib.PAYMASTER_DATA_OFFSET;

    function __BasePaymaster_init(
        address _owner,
        IEntryPoint _entryPoint
    ) internal {
        _validateEntryPointInterface(_entryPoint);
        owner = _owner;
        entryPoint = _entryPoint;
    }

    //sanity check: make sure this EntryPoint was compiled against the same
    // IEntryPoint of this paymaster
    function _validateEntryPointInterface(
        IEntryPoint _entryPoint
    ) internal virtual {
        require(
            IERC165(address(_entryPoint)).supportsInterface(
                type(IEntryPoint).interfaceId
            ),
            "IEntryPoint interface mismatch"
        );
    }

    /// @inheritdoc IPaymaster
    function validatePaymasterUserOp(
        PackedUserOperation calldata userOp,
        bytes32 userOpHash,
        uint256 maxCost
    ) external override returns (bytes memory context, uint256 validationData) {
        _requireFromEntryPoint();
        return _validatePaymasterUserOp(userOp, userOpHash, maxCost);
    }

    /**
     * Validate a user operation.
     * @param userOp     - The user operation.
     * @param userOpHash - The hash of the user operation.
     * @param maxCost    - The maximum cost of the user operation.
     */
    function _validatePaymasterUserOp(
        PackedUserOperation calldata userOp,
        bytes32 userOpHash,
        uint256 maxCost
    ) internal virtual returns (bytes memory context, uint256 validationData);

    /// @inheritdoc IPaymaster
    function postOp(
        PostOpMode mode,
        bytes calldata context,
        uint256 actualGasCost,
        uint256 actualUserOpFeePerGas
    ) external override {
        _requireFromEntryPoint();
        _postOp(mode, context, actualGasCost, actualUserOpFeePerGas);
    }

    /**
     * Post-operation handler.
     * (verified to be called only through the entryPoint)
     * @dev If subclass returns a non-empty context from validatePaymasterUserOp,
     *      it must also implement this method.
     * @param mode          - Enum with the following options:
     *                        opSucceeded - User operation succeeded.
     *                        opReverted  - User op reverted. The paymaster still has to pay for gas.
     *                        postOpReverted - never passed in a call to postOp().
     * @param context       - The context value returned by validatePaymasterUserOp
     * @param actualGasCost - Actual gas used so far (without this postOp call).
     * @param actualUserOpFeePerGas - the gas price this UserOp pays. This value is based on the UserOp's maxFeePerGas
     *                        and maxPriorityFee (and basefee)
     *                        It is not the same as tx.gasprice, which is what the bundler pays.
     */
    function _postOp(
        PostOpMode mode,
        bytes calldata context,
        uint256 actualGasCost,
        uint256 actualUserOpFeePerGas
    ) internal virtual {
        (mode, context, actualGasCost, actualUserOpFeePerGas); // unused params
        // subclass must override this method if validatePaymasterUserOp returns a context
        revert("must override");
    }

    /**
     * Add a deposit for this paymaster, used for paying for transaction fees.
     */
    function deposit() public payable {
        entryPoint.depositTo{value: msg.value}(address(this));
    }

    /**
     * Withdraw value from the deposit.
     * @param withdrawAddress - Target to send to.
     * @param amount          - Amount to withdraw.
     */
    function withdrawTo(
        address payable withdrawAddress,
        uint256 amount
    ) public onlyOwner {
        entryPoint.withdrawTo(withdrawAddress, amount);
    }

    /**
     * Add stake for this paymaster.
     * This method can also carry eth value to add to the current stake.
     * @param unstakeDelaySec - The unstake delay for this paymaster. Can only be increased.
     */
    function addStake(uint32 unstakeDelaySec) external payable {
        entryPoint.addStake{value: msg.value}(unstakeDelaySec);
    }

    /**
     * Return current paymaster's deposit on the entryPoint.
     */
    function getDeposit() public view returns (uint256) {
        return entryPoint.balanceOf(address(this));
    }

    /**
     * Unlock the stake, in order to withdraw it.
     * The paymaster can't serve requests once unlocked, until it calls addStake again
     */
    function unlockStake() external onlyOwner {
        entryPoint.unlockStake();
    }

    /**
     * Withdraw the entire paymaster's stake.
     * stake must be unlocked first (and then wait for the unstakeDelay to be over)
     * @param withdrawAddress - The address to send withdrawn value.
     */
    function withdrawStake(address payable withdrawAddress) external onlyOwner {
        entryPoint.withdrawStake(withdrawAddress);
    }

    /**
     * Validate the call is made from a valid entrypoint
     */
    function _requireFromEntryPoint() internal virtual {
        require(msg.sender == address(entryPoint), "Sender not EntryPoint");
    }

    modifier onlyOwner() {
        _onlyOwner();
        _;
    }

    function _onlyOwner() internal view {
        require(
            msg.sender == owner || msg.sender == address(this),
            "only owner"
        );
    }

    /// @inheritdoc IVersion
    function getVersion() external pure virtual returns (uint16);
}

// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.28;

import {BasePaymasterV1, IEntryPoint} from "./BasePaymasterV1.sol";
import {IDecentPaymasterV1} from "../../interfaces/decent/deployables/IDecentPaymasterV1.sol";
import {IVersion} from "../../interfaces/decent/deployables/IVersion.sol";
import {PackedUserOperation, IPaymaster} from "@account-abstraction/contracts/interfaces/IPaymaster.sol";
import {ERC165} from "@openzeppelin/contracts/utils/introspection/ERC165.sol";
import "@openzeppelin/contracts/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts/proxy/utils/UUPSUpgradeable.sol";

contract DecentPaymasterV1 is
    IDecentPaymasterV1,
    BasePaymasterV1,
    ERC165,
    UUPSUpgradeable,
    Initializable
{
    // Mapping: strategy address => function selector => is approved
    mapping(address => mapping(bytes4 => bool)) public approvedFunctions;

    event FunctionApproved(address strategy, bytes4 selector, bool approved);

    error UnauthorizedStrategy();
    error InvalidCallDataLength();
    error ZeroAddressStrategy();
    error InvalidArrayLength();

    constructor() {
        _disableInitializers();
    }

    function initialize(
        address owner,
        address entryPoint
    ) public virtual initializer {
        _initialize(owner, entryPoint);
    }

    function _initialize(address owner, address entryPoint) internal virtual {
        __BasePaymaster_init(owner, IEntryPoint(entryPoint));
    }

    /**
     * Add or remove approved functions for a strategy contract
     * @param strategy The strategy contract address
     * @param selectors Array of function selectors to approve/disapprove
     * @param approved Whether to approve or remove approval for the selectors
     */
    function setStrategyFunctionApproval(
        address strategy,
        bytes4[] calldata selectors,
        bool[] calldata approved
    ) external onlyOwner {
        if (strategy == address(0)) revert ZeroAddressStrategy();
        if (selectors.length != approved.length) revert InvalidArrayLength();
        for (uint256 i = 0; i < selectors.length; i++) {
            approvedFunctions[strategy][selectors[i]] = approved[i];
            emit FunctionApproved(strategy, selectors[i], approved[i]);
        }
    }

    /**
     * Check if a function is approved for a strategy
     * @param strategy The strategy contract address
     * @param selector The function selector to check
     * @return bool Whether the function is approved
     */
    function isFunctionApproved(
        address strategy,
        bytes4 selector
    ) public view returns (bool) {
        return approvedFunctions[strategy][selector];
    }

    /// @inheritdoc BasePaymasterV1
    function _validatePaymasterUserOp(
        PackedUserOperation calldata userOp,
        bytes32,
        uint256
    )
        internal
        view
        override
        returns (bytes memory context, uint256 validationData)
    {
        bytes calldata callData = userOp.callData;

        // Require minimum length for selector and target address
        if (callData.length < 24) {
            revert InvalidCallDataLength();
        }

        // Extract function selector and target address
        bytes4 selector = bytes4(callData[:4]);
        address target;
        assembly {
            target := shr(96, calldataload(add(callData.offset, 4)))
        }

        // Verify the function is approved for this strategy
        if (!isFunctionApproved(target, selector)) {
            revert UnauthorizedStrategy();
        }

        return (abi.encode(), 0);
    }

    /// @inheritdoc ERC165
    function supportsInterface(
        bytes4 interfaceId
    ) public view override(ERC165) returns (bool) {
        return
            interfaceId == type(IPaymaster).interfaceId ||
            interfaceId == type(IDecentPaymasterV1).interfaceId ||
            super.supportsInterface(interfaceId);
    }

    function _authorizeUpgrade(
        address newImplementation
    ) internal view override {
        (newImplementation);
        _onlyOwner();
    }

    /// @inheritdoc IVersion
    function getVersion() external pure override returns (uint16) {
        return 1;
    }
}

// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.23;

import "@openzeppelin/contracts/utils/Create2.sol";
import "@openzeppelin/contracts/proxy/ERC1967/ERC1967Proxy.sol";

import "./DecentPaymasterV1.sol";

contract DecentPaymasterV1Factory {
    DecentPaymasterV1 public immutable paymasterImplementation;
    IEntryPoint public immutable entryPoint;

    constructor(IEntryPoint _entryPoint) {
        paymasterImplementation = new DecentPaymasterV1();
        entryPoint = _entryPoint;
    }

    /**
     * create an account, and return its address.
     * returns the address even if the account is already deployed.
     * Note that during UserOperation execution, this method is called only if the account is not deployed.
     * This method returns an existing account address so that entryPoint.getSenderAddress() would work even after account creation
     */
    function createPaymaster(
        address owner,
        uint256 salt
    ) public returns (DecentPaymasterV1 ret) {
        address addr = getAddress(owner, salt);
        uint256 codeSize = addr.code.length;
        if (codeSize > 0) {
            return DecentPaymasterV1(payable(addr));
        }
        ret = DecentPaymasterV1(
            payable(
                new ERC1967Proxy{salt: bytes32(salt)}(
                    address(paymasterImplementation),
                    abi.encodeCall(
                        DecentPaymasterV1.initialize,
                        (owner, address(entryPoint))
                    )
                )
            )
        );
    }

    /**
     * calculate the counterfactual address of this account as it would be returned by createAccount()
     */
    function getAddress(
        address owner,
        uint256 salt
    ) public view returns (address) {
        return
            Create2.computeAddress(
                bytes32(salt),
                keccak256(
                    abi.encodePacked(
                        type(ERC1967Proxy).creationCode,
                        abi.encode(
                            address(paymasterImplementation),
                            abi.encodeCall(
                                DecentPaymasterV1.initialize,
                                (owner, address(entryPoint))
                            )
                        )
                    )
                )
            );
    }
}

