// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.28;

import {IVersion} from "../../interfaces/decent/deployables/IVersion.sol";
import {IFractalModuleV1} from "../../interfaces/decent/deployables/IFractalModuleV1.sol";
import {GuardableModule, Enum} from "@gnosis-guild/zodiac/contracts/core/GuardableModule.sol";

/**
 * Implementation of [IFractalModule](./interfaces/IFractalModule.md).
 *
 * A Safe module contract that allows for a "parent-child" DAO relationship.
 *
 * Adding the module allows for a designated set of addresses to execute
 * transactions on the Safe, which in our implementation is the set of parent
 * DAOs.
 */
contract FractalModuleV1 is IVersion, IFractalModuleV1, GuardableModule {
    /** Mapping of whether an address is a controller (typically a parentDAO). */
    mapping(address => bool) public controllers;

    event ControllersAdded(address[] controllers);
    event ControllersRemoved(address[] controllers);

    error Unauthorized();
    error TxFailed();

    /** Allows only authorized controllers to execute transactions on the Safe. */
    modifier onlyAuthorized() {
        if (owner() != msg.sender && !controllers[msg.sender])
            revert Unauthorized();
        _;
    }

    constructor() {
        _disableInitializers();
    }

    /**
     * Initialize function, will be triggered when a new instance is deployed.
     *
     * @param initializeParams encoded initialization parameters: `address _owner`,
     * `address _avatar`, `address _target`, `address[] memory _controllers`
     */
    function setUp(bytes memory initializeParams) public override initializer {
        (
            address _owner, // controlling DAO
            address _avatar,
            address _target,
            address[] memory _controllers // authorized controllers
        ) = abi.decode(
                initializeParams,
                (address, address, address, address[])
            );

        __Ownable_init(msg.sender);
        setAvatar(_avatar);
        setTarget(_target);
        addControllers(_controllers);
        transferOwnership(_owner);
    }

    /** @inheritdoc IFractalModuleV1*/
    function removeControllers(
        address[] memory _controllers
    ) external onlyOwner {
        uint256 controllersLength = _controllers.length;
        for (uint256 i; i < controllersLength; ) {
            controllers[_controllers[i]] = false;
            unchecked {
                ++i;
            }
        }
        emit ControllersRemoved(_controllers);
    }

    /** @inheritdoc IFractalModuleV1*/
    function execTx(bytes memory execTxData) public onlyAuthorized {
        (
            address _target,
            uint256 _value,
            bytes memory _data,
            Enum.Operation _operation
        ) = abi.decode(execTxData, (address, uint256, bytes, Enum.Operation));
        if (!exec(_target, _value, _data, _operation)) revert TxFailed();
    }

    /** @inheritdoc IFractalModuleV1*/
    function addControllers(address[] memory _controllers) public onlyOwner {
        uint256 controllersLength = _controllers.length;
        for (uint256 i; i < controllersLength; ) {
            controllers[_controllers[i]] = true;
            unchecked {
                ++i;
            }
        }
        emit ControllersAdded(_controllers);
    }

    /// @inheritdoc IVersion
    function getVersion() external pure virtual override returns (uint16) {
        return 1;
    }
}

contracts/deployables/strategies/BaseQuo.content:
// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.28;

import {IVersion} from "../../interfaces/decent/deployables/IVersion.sol";
import {OwnableUpgradeable} from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";

/**
 * An Azorius extension contract that enables percent based quorums.
 * Intended to be implemented by [BaseStrategy](./BaseStrategy.md) implementations.
 */
abstract contract BaseQuorumPercentV1 is IVersion, OwnableUpgradeable {
    /** The numerator to use when calculating quorum (adjustable). */
    uint256 public quorumNumerator;

    /** The denominator to use when calculating quorum (1,000,000). */
    uint256 public constant QUORUM_DENOMINATOR = 1_000_000;

    /** Ensures the numerator cannot be larger than the denominator. */
    error InvalidQuorumNumerator();

    event QuorumNumeratorUpdated(uint256 quorumNumerator);

    /**
     * Updates the quorum required for future Proposals.
     *
     * @param _quorumNumerator numerator to use when calculating quorum (over 1,000,000)
     */
    function updateQuorumNumerator(
        uint256 _quorumNumerator
    ) public virtual onlyOwner {
        _updateQuorumNumerator(_quorumNumerator);
    }

    /** Internal implementation of `updateQuorumNumerator`. */
    function _updateQuorumNumerator(uint256 _quorumNumerator) internal virtual {
        if (_quorumNumerator > QUORUM_DENOMINATOR)
            revert InvalidQuorumNumerator();

        quorumNumerator = _quorumNumerator;

        emit QuorumNumeratorUpdated(_quorumNumerator);
    }

    /**
     * Calculates whether a vote meets quorum. This is calculated based on yes votes + abstain
     * votes.
     *
     * @param _totalSupply the total supply of tokens
     * @param _yesVotes number of votes in favor
     * @param _abstainVotes number of votes abstaining
     * @return bool whether the total number of yes votes + abstain meets the quorum
     */
    function meetsQuorum(
        uint256 _totalSupply,
        uint256 _yesVotes,
        uint256 _abstainVotes
    ) public view returns (bool) {
        return
            _yesVotes + _abstainVotes >=
            (_totalSupply * quorumNumerator) / QUORUM_DENOMINATOR;
    }

    /**
     * Calculates the total number of votes required for a proposal to meet quorum.
     *
     * @param _proposalId The ID of the proposal to get quorum votes for
     * @return uint256 The quantity of votes required to meet quorum
     */
    function quorumVotes(
        uint32 _proposalId
    ) public view virtual returns (uint256);

    /// @inheritdoc IVersion
    function getVersion() external pure virtual returns (uint16);
}

contracts/deployables/strategies/BaseStr.content:
// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.28;

import {IVersion} from "../../interfaces/decent/deployables/IVersion.sol";
import {IAzoriusV1} from "../../interfaces/decent/deployables/IAzoriusV1.sol";
import {IBaseStrategyV1} from "../../interfaces/decent/deployables/IBaseStrategyV1.sol";
import {FactoryFriendly} from "@gnosis-guild/zodiac/contracts/factory/FactoryFriendly.sol";
import {OwnableUpgradeable} from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";

/**
 * The base abstract contract for all voting strategies in Azorius.
 */
abstract contract BaseStrategyV1 is
    IVersion,
    OwnableUpgradeable,
    FactoryFriendly,
    IBaseStrategyV1
{
    event AzoriusSet(address indexed azoriusModule);
    event StrategySetUp(address indexed azoriusModule, address indexed owner);

    error OnlyAzorius();

    IAzoriusV1 public azoriusModule;

    /**
     * Ensures that only the [Azorius](./Azorius.md) contract that pertains to this
     * [BaseStrategy](./BaseStrategy.md) can call functions on it.
     */
    modifier onlyAzorius() {
        if (msg.sender != address(azoriusModule)) revert OnlyAzorius();
        _;
    }

    constructor() {
        _disableInitializers();
    }

    /** @inheritdoc IBaseStrategyV1*/
    function setAzorius(address _azoriusModule) external onlyOwner {
        azoriusModule = IAzoriusV1(_azoriusModule);
        emit AzoriusSet(_azoriusModule);
    }

    /** @inheritdoc IBaseStrategyV1*/
    function initializeProposal(bytes memory _data) external virtual;

    /** @inheritdoc IBaseStrategyV1*/
    function isPassed(uint32 _proposalId) external view virtual returns (bool);

    /** @inheritdoc IBaseStrategyV1*/
    function isProposer(address _address) external view virtual returns (bool);

    /** @inheritdoc IBaseStrategyV1*/
    function votingEndBlock(
        uint32 _proposalId
    ) external view virtual returns (uint32);

    /**
     * Sets the address of the [Azorius](Azorius.md) module contract.
     *
     * @param _azoriusModule address of the Azorius module
     */
    function _setAzorius(address _azoriusModule) internal {
        azoriusModule = IAzoriusV1(_azoriusModule);
        emit AzoriusSet(_azoriusModule);
    }

    /// @inheritdoc IVersion
    function getVersion() external pure virtual returns (uint16);
}

