// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.28;

import {IKeyValuePairs} from "../interfaces/decent/singletons/IKeyValuePairs.sol";

/**
 * Implementation of [IKeyValuePairs](./interfaces/IKeyValuePairs.md), a utility
 * contract to log key / value pair events for the calling address.
 */
contract KeyValuePairs is IKeyValuePairs {
    event ValueUpdated(address indexed theAddress, string key, string value);

    error IncorrectValueCount();

    /** @inheritdoc IKeyValuePairs*/
    function updateValues(
        string[] memory _keys,
        string[] memory _values
    ) external {
        uint256 keyCount = _keys.length;

        if (keyCount != _values.length) revert IncorrectValueCount();

        for (uint256 i; i < keyCount; ) {
            emit ValueUpdated(msg.sender, _keys[i], _values[i]);
            unchecked {
                ++i;
            }
        }
    }
}

contracts/utilities/DecentHatsCreationMo.content:
// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.28;

import {DecentHatsModuleUtils} from "./DecentHatsModuleUtils.sol";
import {IERC6551Registry} from "../interfaces/ERC6551/IERC6551Registry.sol";
import {IHats} from "../interfaces/hats/IHats.sol";
import {IHatsModuleFactory} from "../interfaces/hats/IHatsModuleFactory.sol";
import {Enum} from "@gnosis.pm/safe-contracts/contracts/common/Enum.sol";
import {IAvatar} from "@gnosis-guild/zodiac/contracts/interfaces/IAvatar.sol";
import {ModuleProxyFactory} from "@gnosis-guild/zodiac/contracts/factory/ModuleProxyFactory.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";

contract DecentHatsCreationModule is DecentHatsModuleUtils {
    struct TopHatParams {
        string details;
        string imageURI;
    }

    struct AdminHatParams {
        string details;
        string imageURI;
        bool isMutable;
    }

    struct CreateTreeParams {
        IHats hatsProtocol;
        IERC6551Registry erc6551Registry;
        IHatsModuleFactory hatsModuleFactory;
        ModuleProxyFactory moduleProxyFactory;
        address keyValuePairs;
        address decentAutonomousAdminImplementation;
        address hatsAccountImplementation;
        address hatsElectionsEligibilityImplementation;
        TopHatParams topHat;
        AdminHatParams adminHat;
        HatParams[] hats;
    }

    /* /////////////////////////////////////////////////////////////////////////////
                        EXTERNAL FUNCTIONS
    ///////////////////////////////////////////////////////////////////////////// */
    /**
     * @notice For a safe without any roles previously created on it, this function should be called. It sets up the
     * top hat and admin hat, as well as any other hats and their streams that are provided, then transfers the top hat
     * to the calling safe.
     *
     * @notice This contract should be enabled a module on the Safe for which the role(s) are to be created, and disabled after.
     *
     * @dev For each hat that is included, if the hat is:
     *  - termed, its stream funds on are targeted directly at the nominated wearer. The wearer should directly call `withdraw-`
     *    on the Sablier contract.
     *  - untermed, its stream funds are targeted at the hat's smart account. In order to withdraw funds from the stream, the
     * hat's smart account must be the one call to `withdraw-` on the Sablier contract, setting the recipient arg to its wearer.
     *
     * @dev In order for a Safe to seamlessly create roles even if it has never previously created a role and thus has
     * no hat tree, we defer the creation of the hat tree and its setup to this contract. This way, in a single tx block,
     * the resulting topHatId of the newly created hat can be used to create an admin hat and any other hats needed.
     * We also make use of `KeyValuePairs` to associate the topHatId with the Safe.
     *
     * @param treeParams The parameters for creating the Hat Tree with Roles
     */
    function createAndDeclareTree(
        CreateTreeParams calldata treeParams
    ) external {
        // Create Top Hat
        (uint256 topHatId, address topHatAccount) = _processTopHat(
            treeParams.hatsProtocol,
            treeParams.erc6551Registry,
            treeParams.hatsAccountImplementation,
            treeParams.keyValuePairs,
            treeParams.topHat
        );

        // Create Admin Hat
        uint256 adminHatId = _processAdminHat(
            treeParams.hatsProtocol,
            treeParams.erc6551Registry,
            treeParams.hatsAccountImplementation,
            topHatId,
            topHatAccount,
            treeParams.moduleProxyFactory,
            treeParams.decentAutonomousAdminImplementation,
            treeParams.adminHat
        );

        // Create Role Hats
        _processRoleHats(
            CreateRoleHatsParams({
                hatsProtocol: treeParams.hatsProtocol,
                erc6551Registry: treeParams.erc6551Registry,
                hatsAccountImplementation: treeParams.hatsAccountImplementation,
                topHatId: topHatId,
                topHatAccount: topHatAccount,
                hatsModuleFactory: treeParams.hatsModuleFactory,
                hatsElectionsEligibilityImplementation: treeParams
                    .hatsElectionsEligibilityImplementation,
                adminHatId: adminHatId,
                hats: treeParams.hats,
                keyValuePairs: treeParams.keyValuePairs
            })
        );
    }

    /* /////////////////////////////////////////////////////////////////////////////
                        INTERNAL FUNCTIONS
    ///////////////////////////////////////////////////////////////////////////// */

    function _processTopHat(
        IHats hatsProtocol,
        IERC6551Registry erc6551Registry,
        address hatsAccountImplementation,
        address keyValuePairs,
        TopHatParams calldata topHat
    ) internal returns (uint256 topHatId, address topHatAccount) {
        // Call lastTopHatId() and properly decode the response
        (bool success, bytes memory data) = address(hatsProtocol).call(
            abi.encodeWithSignature("lastTopHatId()")
        );
        require(success, "Failed to get lastTopHatId");
        topHatId = (abi.decode(data, (uint256)) + 1) << 224;

        // Mint Top Hat to the Safe
        IAvatar(msg.sender).execTransactionFromModule(
            address(hatsProtocol),
            0,
            abi.encodeWithSignature(
                "mintTopHat(address,string,string)",
                msg.sender,
                topHat.details,
                topHat.imageURI
            ),
            Enum.Operation.Call
        );

        // Create Top Hat's ERC6551 Account
        topHatAccount = erc6551Registry.createAccount(
            hatsAccountImplementation,
            SALT,
            block.chainid,
            address(hatsProtocol),
            topHatId
        );

        // Declare Top Hat ID to Safe via KeyValuePairs
        string[] memory keys = new string[](1);
        string[] memory values = new string[](1);
        keys[0] = "topHatId";
        values[0] = Strings.toString(topHatId);
        IAvatar(msg.sender).execTransactionFromModule(
            keyValuePairs,
            0,
            abi.encodeWithSignature(
                "updateValues(string[],string[])",
                keys,
                values
            ),
            Enum.Operation.Call
        );
    }

    function _processAdminHat(
        IHats hatsProtocol,
        IERC6551Registry erc6551Registry,
        address hatsAccountImplementation,
        uint256 topHatId,
        address topHatAccount,
        ModuleProxyFactory moduleProxyFactory,
        address decentAutonomousAdminImplementation,
        AdminHatParams calldata adminHat
    ) internal returns (uint256 adminHatId) {
        // Create Admin Hat
        adminHatId = hatsProtocol.getNextId(topHatId);
        IAvatar(msg.sender).execTransactionFromModule(
            address(hatsProtocol),
            0,
            abi.encodeWithSignature(
                "createHat(uint256,string,uint32,address,address,bool,string)",
                topHatId,
                adminHat.details,
                1, // only one Admin Hat
                topHatAccount,
                topHatAccount,
                adminHat.isMutable,
                adminHat.imageURI
            ),
            Enum.Operation.Call
        );

        // Create Admin Hat's ERC6551 Account
        erc6551Registry.createAccount(
            hatsAccountImplementation,
            SALT,
            block.chainid,
            address(hatsProtocol),
            adminHatId
        );

        // Deploy Decent Autonomous Admin Module, which will wear the Admin Hat
        address autonomousAdmin = moduleProxyFactory.deployModule(
            decentAutonomousAdminImplementation,
            abi.encodeWithSignature("setUp(bytes)", bytes("")),
            uint256(
                keccak256(
                    abi.encodePacked(
                        // for the salt, we'll concatenate our static salt
                        // with the Admin Hat ID
                        SALT,
                        adminHatId
                    )
                )
            )
        );

        // Mint Hat to the Decent Autonomous Admin Module
        IAvatar(msg.sender).execTransactionFromModule(
            address(hatsProtocol),
            0,
            abi.encodeWithSignature(
                "mintHat(uint256,address)",
                adminHatId,
                autonomousAdmin
            ),
            Enum.Operation.Call
        );
    }
}

contracts/utilities/DecentHatsModificati.content:
// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.28;

import {DecentHatsModuleUtils} from "./DecentHatsModuleUtils.sol";

contract DecentHatsModificationModule is DecentHatsModuleUtils {
    /**
     * @notice Creates a new termed or untermed role hat and any streams on it.
     *
     * @notice This contract should be enabled a module on the Safe for which the role is to be created, and disabled after.
     *
     * @dev Stream funds on untermed Roles are targeted at the hat's smart account. In order to withdraw funds from the stream, the
     * hat's smart account must be the one call to `withdraw-` on the Sablier contract, setting the recipient arg to its wearer.
     *
     * @dev Stream funds on termed Roles are targeted directly at the nominated wearer.
     * The wearer should directly call `withdraw-` on the Sablier contract.
     *
     * @dev Role hat creation, minting, smart account creation and stream creation are handled here in order
     * to avoid a race condition where not more than one active proposal to create a new role can exist at a time.
     * See: https://github.com/decentdao/decent-interface/issues/2402
     *
     * @param roleHatsParams An array of params for each role hat to be created.
     */
    function createRoleHats(
        CreateRoleHatsParams calldata roleHatsParams
    ) external {
        _processRoleHats(roleHatsParams);
    }
}

contracts/utilities/DecentHatsModuleUtil.content:
// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.28;

import {IERC6551Registry} from "../interfaces/ERC6551/IERC6551Registry.sol";
import {IHats} from "../interfaces/hats/IHats.sol";
import {IHatsModuleFactory} from "../interfaces/hats/IHatsModuleFactory.sol";
import {ISablierV2LockupLinear} from "../interfaces/sablier/ISablierV2LockupLinear.sol";
import {LockupLinear, Broker} from "../interfaces/sablier/types/DataTypes.sol";
import {Enum} from "@gnosis.pm/safe-contracts/contracts/common/Enum.sol";
import {IAvatar} from "@gnosis-guild/zodiac/contracts/interfaces/IAvatar.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";

abstract contract DecentHatsModuleUtils {
    bytes32 public constant SALT =
        0x5d0e6ce4fd951366cc55da93f6e79d8b81483109d79676a04bcc2bed6a4b5072;

    struct SablierStreamParams {
        ISablierV2LockupLinear sablier;
        address sender;
        address asset;
        LockupLinear.Timestamps timestamps;
        Broker broker;
        uint128 totalAmount;
        bool cancelable;
        bool transferable;
    }

    struct HatParams {
        address wearer;
        string details;
        string imageURI;
        SablierStreamParams[] sablierStreamsParams;
        uint128 termEndDateTs; // If 0, this is an untermed Hat
        uint32 maxSupply;
        bool isMutable;
    }

    struct CreateRoleHatsParams {
        IHats hatsProtocol;
        IERC6551Registry erc6551Registry;
        address hatsAccountImplementation;
        uint256 topHatId;
        address topHatAccount;
        address keyValuePairs;
        IHatsModuleFactory hatsModuleFactory;
        address hatsElectionsEligibilityImplementation;
        uint256 adminHatId;
        HatParams[] hats;
    }

    function _processRoleHats(
        CreateRoleHatsParams memory roleHatsParams
    ) internal {
        for (uint256 i = 0; i < roleHatsParams.hats.length; ) {
            HatParams memory hatParams = roleHatsParams.hats[i];

            // Create eligibility module if needed
            address eligibilityAddress = _createEligibilityModule(
                roleHatsParams.hatsProtocol,
                roleHatsParams.hatsModuleFactory,
                roleHatsParams.hatsElectionsEligibilityImplementation,
                roleHatsParams.topHatId,
                roleHatsParams.topHatAccount,
                roleHatsParams.adminHatId,
                hatParams.termEndDateTs
            );

            // Create and Mint the Role Hat
            uint256 hatId = _createAndMintHat(
                roleHatsParams.hatsProtocol,
                roleHatsParams.adminHatId,
                hatParams,
                eligibilityAddress,
                roleHatsParams.topHatAccount
            );

            // Get the stream recipient (based on termed or not)
            address streamRecipient = _setupStreamRecipient(
                roleHatsParams.erc6551Registry,
                roleHatsParams.hatsAccountImplementation,
                address(roleHatsParams.hatsProtocol),
                hatParams.termEndDateTs,
                hatParams.wearer,
                hatId
            );

            // Create streams
            _processSablierStreams(
                hatParams.sablierStreamsParams,
                streamRecipient,
                roleHatsParams.keyValuePairs,
                hatId
            );

            unchecked {
                ++i;
            }
        }
    }

    function _createEligibilityModule(
        IHats hatsProtocol,
        IHatsModuleFactory hatsModuleFactory,
        address hatsElectionsEligibilityImplementation,
        uint256 topHatId,
        address topHatAccount,
        uint256 adminHatId,
        uint128 termEndDateTs
    ) private returns (address) {
        // If the Hat is termed, create the eligibility module
        if (termEndDateTs != 0) {
            return
                hatsModuleFactory.createHatsModule(
                    hatsElectionsEligibilityImplementation,
                    hatsProtocol.getNextId(adminHatId),
                    abi.encode(topHatId, uint256(0)), // [BALLOT_BOX_ID, ADMIN_HAT_ID]
                    abi.encode(termEndDateTs),
                    uint256(SALT)
                );
        }

        // Otherwise, return the Top Hat account
        return topHatAccount;
    }

    function _createAndMintHat(
        IHats hatsProtocol,
        uint256 adminHatId,
        HatParams memory hat,
        address eligibilityAddress,
        address topHatAccount
    ) private returns (uint256) {
        // Grab the next Hat ID (before creating it)
        uint256 hatId = hatsProtocol.getNextId(adminHatId);

        // Create the new Hat
        IAvatar(msg.sender).execTransactionFromModule(
            address(hatsProtocol),
            0,
            abi.encodeWithSignature(
                "createHat(uint256,string,uint32,address,address,bool,string)",
                adminHatId,
                hat.details,
                hat.maxSupply,
                eligibilityAddress,
                topHatAccount,
                hat.isMutable,
                hat.imageURI
            ),
            Enum.Operation.Call
        );

        // If the Hat is termed, nominate the wearer as the eligible member
        if (hat.termEndDateTs != 0) {
            address[] memory nominatedWearers = new address[](1);
            nominatedWearers[0] = hat.wearer;

            IAvatar(msg.sender).execTransactionFromModule(
                eligibilityAddress,
                0,
                abi.encodeWithSignature(
                    "elect(uint128,address[])",
                    hat.termEndDateTs,
                    nominatedWearers
                ),
                Enum.Operation.Call
            );
        }

        // Mint the Hat
        IAvatar(msg.sender).execTransactionFromModule(
            address(hatsProtocol),
            0,
            abi.encodeWithSignature(
                "mintHat(uint256,address)",
                hatId,
                hat.wearer
            ),
            Enum.Operation.Call
        );
        return hatId;
    }

    // Exists to avoid stack too deep errors
    function _setupStreamRecipient(
        IERC6551Registry erc6551Registry,
        address hatsAccountImplementation,
        address hatsProtocol,
        uint128 termEndDateTs,
        address wearer,
        uint256 hatId
    ) private returns (address) {
        // If the hat is termed, the wearer is the stream recipient
        if (termEndDateTs != 0) {
            return wearer;
        }

        // Otherwise, the Hat's smart account is the stream recipient
        return
            erc6551Registry.createAccount(
                hatsAccountImplementation,
                SALT,
                block.chainid,
                hatsProtocol,
                hatId
            );
    }

    function _processSablierStreams(
        SablierStreamParams[] memory streamParams,
        address streamRecipient,
        address keyValuePairs,
        uint256 hatId
    ) private {
        for (uint256 i = 0; i < streamParams.length; ) {
            SablierStreamParams memory sablierStreamParams = streamParams[i];

            // Approve tokens for Sablier
            IAvatar(msg.sender).execTransactionFromModule(
                sablierStreamParams.asset,
                0,
                abi.encodeWithSignature(
                    "approve(address,uint256)",
                    sablierStreamParams.sablier,
                    sablierStreamParams.totalAmount
                ),
                Enum.Operation.Call
            );
            uint256 streamId = ISablierV2LockupLinear(
                sablierStreamParams.sablier
            ).nextStreamId();

            // Proxy the Sablier call through IAvatar
            IAvatar(msg.sender).execTransactionFromModule(
                address(sablierStreamParams.sablier),
                0,
                abi.encodeWithSignature(
                    "createWithTimestamps((address,address,uint128,address,bool,bool,(uint40,uint40,uint40),(address,uint256)))",
                    LockupLinear.CreateWithTimestamps({
                        sender: sablierStreamParams.sender,
                        recipient: streamRecipient,
                        totalAmount: sablierStreamParams.totalAmount,
                        asset: IERC20(sablierStreamParams.asset),
                        cancelable: sablierStreamParams.cancelable,
                        transferable: sablierStreamParams.transferable,
                        timestamps: sablierStreamParams.timestamps,
                        broker: sablierStreamParams.broker
                    })
                ),
                Enum.Operation.Call
            );

            // Update KeyValuePairs with the stream ID and Hat ID
            string[] memory keys = new string[](1);
            string[] memory values = new string[](1);
            keys[0] = "hatIdToStreamId";
            values[0] = string(
                abi.encodePacked(
                    Strings.toString(hatId),
                    ":",
                    Strings.toString(streamId)
                )
            );

            IAvatar(msg.sender).execTransactionFromModule(
                keyValuePairs,
                0,
                abi.encodeWithSignature(
                    "updateValues(string[],string[])",
                    keys,
                    values
                ),
                Enum.Operation.Call
            );

            unchecked {
                ++i;
            }
        }
    }
}

contracts/utilities/DecentSablierStreamM.content:
// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.28;

import {Enum} from "@gnosis.pm/safe-contracts/contracts/common/Enum.sol";
import {IAvatar} from "@gnosis-guild/zodiac/contracts/interfaces/IAvatar.sol";
import {ISablierV2Lockup} from "../interfaces/sablier/ISablierV2Lockup.sol";
import {Lockup} from "../interfaces/sablier/types/DataTypes.sol";

contract DecentSablierStreamManagementModule {
    function withdrawMaxFromStream(
        ISablierV2Lockup sablier,
        address recipientHatAccount,
        uint256 streamId,
        address to
    ) public {
        // Check if there are funds to withdraw
        if (sablier.withdrawableAmountOf(streamId) == 0) {
            return;
        }

        // Proxy the Sablier withdrawMax call through IAvatar (Safe)
        IAvatar(msg.sender).execTransactionFromModule(
            recipientHatAccount,
            0,
            abi.encodeWithSignature(
                "execute(address,uint256,bytes,uint8)",
                address(sablier),
                0,
                abi.encodeWithSignature(
                    "withdrawMax(uint256,address)",
                    streamId,
                    to
                ),
                0
            ),
            Enum.Operation.Call
        );
    }

    function cancelStream(ISablierV2Lockup sablier, uint256 streamId) public {
        // Check if the stream can be cancelled
        Lockup.Status streamStatus = sablier.statusOf(streamId);
        if (
            streamStatus != Lockup.Status.PENDING &&
            streamStatus != Lockup.Status.STREAMING
        ) {
            return;
        }

        IAvatar(msg.sender).execTransactionFromModule(
            address(sablier),
            0,
            abi.encodeWithSignature("cancel(uint256)", streamId),
            Enum.Operation.Call
        );
    }
}
